mapper.select:
select id, case_no, biz_type, biz_id, user_id, case_type, case_status,
       severity, source_status, target_status, summary, detail, retry_count,
       create_time, update_time, handled_time, handler, handle_note
from reconcile_case
where 1 = 1

    and case_status = #{caseStatus}


    and case_type = #{caseType}


    and id > #{lastId}

order by id asc
limit #{pageSize}
